\chapter{Cohomology of sheaves of modules}
\label{chap:Cohomology}

Fix a commutative ring \(R\); for the genus of a curve, \(R\) will be the base field \(k\).
This chapter defines the cohomology of sheaves of \(R\)-modules on a small site as
\(\Ext\)-groups from the constant sheaf, and more generally the cohomology of an object of
the site as \(\Ext\)-groups from a free sheaf of \(R\)-modules; it identifies degree-zero
cohomology with (global) sections and proves the vanishing of degree-one cohomology of the
structure sheaf on an affine open of a scheme. It then develops the Mayer--Vietoris
\((0,1)\)-slice for a sheaf of \(R\)-modules on a site and specializes it to a scheme
covered by two affine opens, producing an explicit description of \(H^1(X,\struct{X/k})\)
as the cokernel of a map of section modules. It then runs the
two-lattice ladder of Chapter~\ref{chap:Algebra} on that cokernel along a finite morphism
to the projective line, proving the finiteness of \(H^1(C, \struct C)\) --- so that the
genus of Definition~\ref{def:genus} is the dimension of a finite-dimensional vector space.
The two closing sections glue a twisted sheaf out of a unit cocycle on a two-chart cover
and prove that the two-cover \(H^1\) of the relative curve --- for the structure sheaf,
and termwise for the twisted sheaf --- commutes with arbitrary change of the affine test
ring.

\section{Cohomology on a site}

Let \((\mathcal C, J)\) be a small site: a small category \(\mathcal C\) with a Grothendieck
topology \(J\). The category of sheaves of \(R\)-modules on \((\mathcal C, J)\) is a
Grothendieck abelian category; in particular it has enough injectives, and all
\(\Ext\)-groups exist and carry \(R\)-module structures.

\begin{definition}[The constant sheaf]
  \label{def:constModuleSheaf}
  \lean{CategoryTheory.Sheaf.constModuleSheaf}
  \leanok
  The constant sheaf \(R_J\) of \(R\)-modules on \((\mathcal C, J)\) with value \(R\): the
  sheafification of the constant presheaf with value \(R\).
\end{definition}

\begin{definition}[Sheaf cohomology]
  \label{def:HModule}
  \lean{CategoryTheory.Sheaf.HModule}
  \uses{def:constModuleSheaf}
  \leanok
  For a sheaf \(F\) of \(R\)-modules on \((\mathcal C, J)\) and \(n \ge 0\), the degree-\(n\)
  cohomology of \(F\) is the \(R\)-module
  \[
    H^n(F) \;=\; \Ext^n\bigl(R_J,\, F\bigr),
  \]
  the \(\Ext\)-group computed in the category of sheaves of \(R\)-modules.
\end{definition}

\begin{definition}[Functoriality]
  \label{def:HModule_map}
  \lean{CategoryTheory.Sheaf.HModule.map}
  \uses{def:HModule}
  \leanok
  A morphism of sheaves \(f : F \to G\) induces an \(R\)-linear map
  \(H^n(F) \to H^n(G)\) for every \(n\), by covariant functoriality of \(\Ext\) in the second
  argument. The identity induces the identity, and a composite induces the composite.
\end{definition}
\begin{proof}
  \leanok
  Functoriality of \(\Ext^n(R_J, -)\); the \(R\)-linearity comes from the \(R\)-linear
  structure of the sheaf category.
\end{proof}

\begin{lemma}[No higher cohomology on injectives]
  \label{lem:HModule_injective_vanishing}
  \lean{CategoryTheory.Sheaf.HModule.instSubsingletonHAddNatOfNat}
  \uses{def:HModule}
  \leanok
  If \(F\) is an injective object of the category of sheaves of \(R\)-modules, then
  \(H^{n+1}(F) = 0\) for every \(n \ge 0\).
\end{lemma}
\begin{proof}
  \leanok
  Positive-degree \(\Ext\)-groups into an injective object vanish.
\end{proof}

\begin{definition}[The adjunction, linearly]
  \label{def:constAdjHomEquiv}
  \lean{CategoryTheory.Sheaf.constantSheafAdjHomLinearEquiv}
  \leanok
  Assume the category \(\mathcal C\) has a terminal object \(\top\). For every \(R\)-module
  \(M\) and every sheaf \(F\) of \(R\)-modules there is an \(R\)-linear equivalence
  \[
    \Hom\bigl(\underline{M},\, F\bigr) \;\cong\; \Hom_R\bigl(M,\, F(\top)\bigr),
  \]
  where \(\underline{M}\) denotes the constant sheaf with value \(M\); it is the hom-bijection
  of the adjunction between the constant-sheaf functor and evaluation at \(\top\).
\end{definition}
\begin{proof}
  \leanok
  The constant-sheaf functor is left adjoint to evaluation at the terminal object. The
  bijection sends \(\varphi\) to the composite of the unit \(M \to \underline{M}(\top)\) with
  \(\varphi_\top\); both this assignment and its inverse are additive and commute with the
  \(R\)-action.
\end{proof}

\begin{definition}[Morphisms out of the constant sheaf are sections]
  \label{def:constHomEquiv}
  \lean{CategoryTheory.Sheaf.constModuleSheafHomEquiv}
  \uses{def:constModuleSheaf, def:constAdjHomEquiv}
  \leanok
  The \(R\)-linear equivalence
  \(\Hom(R_J, F) \cong F(\top)\): specialize \ref{def:constAdjHomEquiv} to \(M = R\) and
  compose with the canonical evaluation \(\Hom_R(R, N) \cong N\), \(u \mapsto u(1)\).
\end{definition}

\begin{lemma}[Naturality]
  \label{lem:constHomEquiv_naturality}
  \lean{CategoryTheory.Sheaf.constModuleSheafHomEquiv_naturality}
  \uses{def:constHomEquiv}
  \leanok
  The equivalence of \ref{def:constHomEquiv} is natural in the sheaf: for
  \(\varphi : R_J \to F\) and \(f : F \to G\), the section corresponding to
  \(f \circ \varphi\) is \(f_\top\) applied to the section corresponding to \(\varphi\).
\end{lemma}
\begin{proof}
  \leanok
  Naturality of the adjunction hom-bijection in the second variable, and naturality of the
  evaluation \(\Hom_R(R, N) \cong N\).
\end{proof}

\begin{definition}[Degree-zero cohomology is global sections]
  \label{def:HModule_linearEquiv0}
  \lean{CategoryTheory.Sheaf.HModule.linearEquiv₀}
  \uses{def:HModule, def:constHomEquiv}
  \leanok
  The \(R\)-linear equivalence \(H^0(F) \cong F(\top)\): the canonical identification
  \(\Ext^0(R_J, F) \cong \Hom(R_J, F)\) followed by \ref{def:constHomEquiv}.
\end{definition}

\begin{lemma}[Naturality in degree zero]
  \label{lem:HModule_linearEquiv0_naturality}
  \lean{CategoryTheory.Sheaf.HModule.linearEquiv₀_naturality}
  \uses{def:HModule_linearEquiv0, def:HModule_map}
  \leanok
  The equivalence \(H^0(F) \cong F(\top)\) of \ref{def:HModule_linearEquiv0} is natural: for
  \(f : F \to G\), applying \(f_\top\) to the section corresponding to \(x \in H^0(F)\)
  yields the section corresponding to the image of \(x\) under \(H^0(f)\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:constHomEquiv_naturality}
  The identification \(\Ext^0 \cong \Hom\) turns composition with the degree-zero class of
  \(f\) into postcomposition with \(f\); conclude by \ref{lem:constHomEquiv_naturality}.
\end{proof}

\section{Cohomology of an object of the site}

For an object \(U\) of \(\mathcal C\), this section defines the cohomology of \(U\) with
coefficients in a sheaf \(F\) of \(R\)-modules as \(\Ext\)-groups from a \emph{free} sheaf

\chapter{Curves over a field}
\label{chap:Curves}

Throughout this chapter \(k\) is a field. As in Chapter~\ref{chap:Challenge}, a \emph{smooth
curve} over \(k\) is a \(k\)-scheme which is smooth of relative dimension one, proper, and
geometrically irreducible over \(k\). This chapter provides the geometric substrate for the
genus: smooth schemes over a field are reduced, so a smooth curve is geometrically integral;
a proper geometrically integral scheme over a field has no global functions besides the
constants; the projective line carries two affine charts with polynomial section rings and
Laurent-polynomial overlap; the section rings of the standard smooth charts of a curve are
Dedekind domains, so the local rings of the curve are valuation rings and its
specialization order has height one; a rational function transcendental over \(k\) therefore
spreads out to a locally quasi-finite morphism \(C \to \PP^1\); and Zariski's main theorem
upgrades it to a finite one.

\section{Smooth algebras over a domain are reduced}

\begin{lemma}[Unramified flat algebras over a domain are reduced]
  \label{lem:unramified_flat_reduced}
  \lean{Algebra.FormallyUnramified.isReduced_of_isDomain}
  \leanok
  Let \(B\) be an integral domain and let \(S\) be a commutative \(B\)-algebra which is
  formally unramified, essentially of finite type, and flat over \(B\). Then \(S\) is reduced.
\end{lemma}
\begin{proof}
  \leanok
  Let \(K = \Frac B\) be the fraction field. The \(K\)-algebra \(K \otimes_B S\) is again
  formally unramified and essentially of finite type, both properties being stable under base
  change, and a formally unramified, essentially of finite type algebra over a field is
  reduced. It therefore suffices to embed \(S\) into \(K \otimes_B S\). The canonical map
  \(s \mapsto 1 \otimes s\) is, up to the isomorphism \(S \cong B \otimes_B S\), obtained from
  the injection \(B \hookrightarrow K\) by tensoring with \(S\); since \(S\) is flat over
  \(B\), it is injective. A subring of a reduced ring is reduced.
\end{proof}

\begin{lemma}[\'Etale algebras over a domain are reduced]
  \label{lem:etale_reduced_domain}
  \lean{Algebra.Etale.isReduced_of_isDomain}
  \leanok
  An \'etale algebra over an integral domain is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:unramified_flat_reduced}
  An \'etale algebra is formally unramified and of finite presentation, in particular
  essentially of finite type, and it is flat. Apply \ref{lem:unramified_flat_reduced}.
\end{proof}

\begin{lemma}[Standard smooth homomorphisms out of a domain]
  \label{lem:standard_smooth_reduced_ringhom}
  \lean{RingHom.IsStandardSmooth.isReduced_of_isDomain}
  \leanok
  Let \(B\) be an integral domain and let \(B \to S\) be a standard smooth ring homomorphism,
  that is, one admitting a presentation \(S = B[x_1,\dots,x_n]/(f_1,\dots,f_c)\) in which the
  Jacobian matrix \((\partial f_u/\partial x_v)_{u,v \le c}\) has invertible determinant in
  \(S\). Then \(S\) is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:etale_reduced_domain}
  By the structure theorem for standard smooth algebras, \(S\) is \'etale over a polynomial
  ring over the base: there are \(m\) and a factorization
  \(B \to B[x_1,\dots,x_m] \to S\) with the second map \'etale. A polynomial ring over an
  integral domain is an integral domain, so \ref{lem:etale_reduced_domain} applies.
\end{proof}

\begin{lemma}[Standard smooth algebras over a domain]
  \label{lem:standard_smooth_reduced}
  \lean{Algebra.IsStandardSmooth.isReduced_of_isDomain}
  \leanok
  A standard smooth algebra over an integral domain is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:standard_smooth_reduced_ringhom}
  The structure homomorphism is a standard smooth ring homomorphism out of a domain; apply
  \ref{lem:standard_smooth_reduced_ringhom}.
\end{proof}

\begin{theorem}[Smooth schemes over a field are reduced]
  \label{thm:smooth_reduced_field}
  \lean{AlgebraicGeometry.Smooth.isReduced_of_field}
  \leanok
  Let \(K\) be a field and let \(X\) be a scheme which is smooth over \(\Spec K\). Then \(X\)
  is reduced.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:standard_smooth_reduced_ringhom}
  A smooth morphism is, locally on the source and the target, standard smooth: every point
  \(x \in X\) has an affine open neighbourhood \(V\), mapping into an affine open \(U\) of the
  base, such that the induced ring homomorphism \(\Gamma(U) \to \Gamma(V)\) is standard
  smooth. Since \(\Spec K\) has a single point and \(U\) is a nonempty open subset containing
  the image of \(x\), we have \(U = \Spec K\), and \(\Gamma(U) \cong K\) is a field, in
  particular a domain. By \ref{lem:standard_smooth_reduced_ringhom} the ring \(\Gamma(V)\) is
  reduced, hence the affine scheme \(V\) is reduced. The opens \(V\) cover \(X\), and a scheme
  covered by reduced open subschemes is reduced.
\end{proof}

\begin{theorem}[Smooth morphisms are geometrically reduced]
  \label{thm:smooth_geometrically_reduced}
  \lean{AlgebraicGeometry.Smooth.geometricallyReduced}
  \leanok
  A smooth morphism of schemes \(f : X \to Y\) is geometrically reduced: for every field \(K\)
  and every morphism \(\Spec K \to Y\), the base change \(X \times_Y \Spec K\) is a reduced
  scheme.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:smooth_reduced_field}
  Smoothness is stable under base change, so the projection
  \(X \times_Y \Spec K \to \Spec K\) is smooth; apply \ref{thm:smooth_reduced_field}.
\end{proof}

\begin{lemma}[Smooth of relative dimension one implies smooth]
  \label{lem:smooth_of_relDim_one}
  \lean{AlgebraicGeometry.Smooth.of_smoothOfRelativeDimension_one}
  \leanok
  A morphism of schemes which is smooth of relative dimension one is smooth.
\end{lemma}
\begin{proof}
  \leanok
  A morphism smooth of some relative dimension is smooth.
\end{proof}

\begin{lemma}[Smooth of a relative dimension implies geometrically reduced]
  \label{lem:relDim_geometrically_reduced}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyReduced}
  \leanok
  For every \(n\), a morphism of schemes which is smooth of relative dimension \(n\) is
  geometrically reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{thm:smooth_geometrically_reduced}
  Such a morphism is smooth; apply \ref{thm:smooth_geometrically_reduced}.
\end{proof}

\begin{theorem}[Smooth and geometrically irreducible implies geometrically integral]
  \label{thm:smooth_geometrically_integral}
  \lean{AlgebraicGeometry.Smooth.geometricallyIntegral}
  \leanok
  A smooth, geometrically irreducible morphism of schemes is geometrically integral: every
  base change to the spectrum of a field is an integral scheme.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:smooth_geometrically_reduced}
  Every base change to the spectrum of a field is reduced
  (\ref{thm:smooth_geometrically_reduced}) and irreducible (geometric irreducibility), and a
  reduced scheme with irreducible --- in particular nonempty --- underlying space is integral.
\end{proof}

\begin{theorem}[Relative-dimension form]
  \label{thm:relDim_geometrically_integral}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyIntegral}
  \leanok
  For every \(n\), a geometrically irreducible morphism of schemes which is smooth of relative
  dimension \(n\) is geometrically integral.
\end{theorem}
